    it("falls back to the first model when the kind has no untagged default model", () => {
      const kit = {
        types: [
          {
            guid: "kind-1",
            models: [
              { guid: "model-first", file: { guid: "file-first" }, tags: [{ guid: "tag-1" }] },
              { guid: "model-second", file: { guid: "file-second" }, tags: [{ guid: "tag-2" }] },
            ],
          },
        ],
