// #region 🔖Header
// [👤compose📚engine💻mcpapp](repo://p/u/compose/b/l/engine/f/mcp-app.tsx)

// 2026 Ueli Saluz <ueli@semio-tech.com>

// Specs: Standalone MCP App entry point. Receives pre-computed diagram data from
// tool results and renders pure SVG. No @compose/ui, @compose/js or Three.js imports.
// Summary: Lightweight MCP App for rendering compose design diagrams as SVG.

// #endregion 🔖Header

import * as React from "react";
import { createRoot } from "react-dom/client";
import { useApp } from "@modelcontextprotocol/ext-apps/react";
import type { App as McpAppInstance } from "@modelcontextprotocol/ext-apps";

// #region 🔖DiagramTypes

interface DiagramPoint {
  guid: string;
  id: string;
  u: number;
  v: number;
