    const minU = Math.min(...us);
    const maxU = Math.max(...us);
    const minV = Math.min(...vs);
    const maxV = Math.max(...vs);
    return {
      minU,
      maxU,
      minV,
      maxV,
      width: Math.max(maxU - minU, MIN_SPAN),
