    event.preventDefault();
    if (size.width <= 0 || size.height <= 0) return;
    const nextZoom = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, zoom * Math.exp(-event.deltaY * ZOOM_STEP)));
    if (Math.abs(nextZoom - zoom) < 0.0001) return;
