                  ? (e) => {
                      e.stopPropagation();
                      toggleConnection(line.guid);
                    }
                  : undefined
              }
              onPointerEnter={() => setHoveredConnection(line.guid)}
              onPointerLeave={() => setHoveredConnection((prev) => (prev === line.guid ? null : prev))}
            />
          );
