        kit_data = {
            "name": "RemoteKit",
            "version": "1.0.0",
            "designs": [
                {"guid": "d1", "name": "Design1", "pieces": [], "connections": []},
            ],
            "types": [
                {"guid": "t1", "name": "Type1", "connectors": []},
            ],
        }
